func removeNthFromEnd(head *ListNode, n int) *ListNode {
    if head == nil {
        return head
    }

    slow, fast := head, head
    for n > 0 {
        fast = fast.Next
        n--
    }

    if fast == nil {
        return slow.Next
    }

    for fast.Next != nil {
        slow = slow.Next
        fast = fast.Next
    }

    slow.Next = slow.Next.Next
    return head
}

func isValid(s string) bool {
    pairs := map[byte]byte{
        '}': '{',
        ']': '[',
        ')': '(',
    }

    stack := make([]byte, 0)

    for _, char := range []byte(s) {
        pair, ok := pairs[char]
        if !ok {
            stack = append(stack, char)
            continue
        }

        if len(stack) == 0 {
            return false
        }

        if stack[len(stack) - 1] != pair {
            return false
        }

        stack = stack[:len(stack) - 1]
    }

    return len(stack) == 0
}

