 func swapPairs(head *ListNode) *ListNode {
    if head == nil || head.Next == nil {
        return head
    }

    next := head.Next
    swapped := swapPairs(next.Next)

    next.Next, head.Next = head, swapped

    return next
}

func reverseKGroup(head *ListNode, k int) *ListNode {
    dummy := &ListNode{Val: 0, Next: head}
    groupPrev := dummy

    for true {
        kth := getKth(groupPrev, k)
        if kth == nil {
            break;
        }
        groupNext := kth.Next

        // reverse group
        prev, curr := kth.Next, groupPrev.Next
        for curr != groupNext {
            tmp := curr.Next
            curr.Next = prev
            prev = curr
            curr = tmp
        }

        tmp := groupPrev.Next
        groupPrev.Next = kth
        groupPrev = tmp
    }
    return dummy.Next
}

func getKth(curr *ListNode, k int) *ListNode {
    for curr != nil && k > 0 {
        curr = curr.Next
        k -= 1
    }
    return curr
}

func removeDuplicates(nums []int) int {
    length := len(nums)
    if length < 2 {
        return length
    }
    k, i := 1, 1
    for i < length {
        if nums[i] != nums[i-1] {
            nums[k] = nums[i]
            k++
        }
        i++
    }
    return k
}

func removeElement(nums []int, val int) int {
    left, right := 0, len(nums)-1

    for left <= right {
        if nums[left] == val {
            nums[left], nums[right] = nums[right], nums[left]
            right--
        } else {
            left++
        }
    }

    return left
}

func strStr(haystack string, needle string) int {
    if haystack == "" && needle == "" {
        return 0
    }
    lh := len(haystack)
    ln := len(needle)
    for i := 0; i < lh; i++ {
        ct := 0
        for j := 0; j < ln; j++ {
            if i+j >= lh {
                return -1
            }
            if needle[j] != haystack[i+j] {
                break
            }
            ct++
        }
        if ct == ln {
            return i
        }
    }
    return -1
}

func search(nums []int, target int) int {
    left, right := 0, len(nums) - 1

    for left <= right {
        mid := (left + right) / 2
        if target == nums[mid] {
            return mid
        }

        // left sorted portion
        if nums[left] <= nums[mid] {
            if target > nums[mid] || target < nums[left] {
                left = mid + 1
            } else {
                right = mid - 1
            }
        // Right sorted portion
        } else {
            if target < nums[mid] || target > nums[right] {
                right = mid - 1
            } else {
                left = mid + 1
            }
        }
    }
    return -1
}

func searchRange(nums []int, target int) []int {
    right := binSearch(nums, target, false)
    left := binSearch(nums, target, true)
    return []int{left, right}
}

func binSearch(nums []int, target int, leftBias bool) int {
    l, r := 0, len(nums)-1
    i := -1
    for l <= r {
        m := (l + r) / 2
        if nums[m] < target {
            l = m + 1
        } else if nums[m] > target {
            r = m - 1
        } else {
            i = m
            if leftBias {
                r = m - 1
            } else {
                l = m + 1
            }
        }
    }
    return i
}

func searchInsert(nums []int, target int) int {
    low, high := 0, len(nums)
    for low < high {
        mid := low + (high - low)/2
        if target > nums[mid] {
            low = mid + 1
        } else {
            high = mid
        }
    }
    return low
}

func isValidSudoku(board [][]byte) bool {
    rows := [9][9]bool{}
    cols := [9][9]bool{}
    squares := [9][9]bool{}

    for r := range 9 {
        for c := range 9 {
            if board[r][c] == '.' {
                continue
            }

            value := board[r][c] - '1'
            s := r/3*3 + c/3
            if rows[r][value] || cols[c][value] || squares[s][value] {
                return false
            }

            rows[r][value] = true
            cols[c][value] = true
            squares[s][value] = true
        }
    }

    return true
}

