import "sort"

func merge(intervals [][]int) [][]int {
    const (
        start = 0
        end   = 1
    )

    sort.SliceStable(intervals, func(i, j int) bool {
        return intervals[i][start] < intervals[j][start]
    })

    res := [][]int{intervals[0]}
    for i := 1; i < len(intervals); i++ {
        currResLastIndex := len(res) - 1
        currEnd := res[currResLastIndex]
        curr := intervals[i]

        if currEnd[end] < curr[start] {
            res = append(res, curr)
        } else if currEnd[end] < curr[end] {
            res[currResLastIndex][end] = curr[end]
        }
    }

    return res
}

func insert(intervals [][]int, newInterval []int) [][]int {

    res := [][]int{}

    for i, currInt := range intervals {
        currStart, currEnd := currInt[0], currInt[1]
        newIntStart, newIntEnd := newInterval[0], newInterval[1]

        if newIntEnd < currStart {
            res = append(res, newInterval)

            res = append(res, intervals[i:]...)

            return res
        } else if newIntStart > currEnd {

            res = append(res, currInt)

        } else {
            newInterval[0] = min(newIntStart, currStart)
            newInterval[1] = max(newIntEnd, currEnd)

        }
    }

    res = append(res, newInterval)

    return res

}
