func uniquePaths(m int, n int) int {
    dp := make([]int, n)
    dp[0] = 1

    for i := 0; i < m; i++ {
        for j := 1; j < n; j++ {
            dp[j] += dp[j-1]
        }
    }

    return dp[n-1]
}

func uniquePathsWithObstacles(obstacleGrid [][]int) int {
    m, n := len(obstacleGrid), len(obstacleGrid[0])

    if m == 0 || n == 0 || obstacleGrid[0][0] == 1 {
        return 0
    }

    dp := make([][]int, m+1)

    for i := 0; i <= m; i++ {
        dp[i] = make([]int, n+1)
    }

    dp[0][1] = 1

    for i := 1; i <= m; i++ {
        for j := 1; j <= n; j++ {
            if obstacleGrid[i-1][j-1] == 1 {
                dp[i][j] = 0
            } else {
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            }
        }
    }

    return dp[m][n];
}

