func searchMatrix(matrix [][]int, target int) bool {
    ROWS := len(matrix)
    COLUMNS := len(matrix[0])

    top := 0
    bot := ROWS - 1

    for top <= bot {
        row := (top + bot) / 2
        if target > matrix[row][len(matrix[row])-1] {
            top = row + 1
        } else if target < matrix[row][0] {
            bot = row - 1
        } else {
            break
        }
    }

    if !(top <= bot) {
        return false
    }

    row := (top + bot) / 2
    left := 0
    right := COLUMNS - 1
    for left <= right {
        middle := (left + right) / 2
        if target > matrix[row][middle] {
            left = middle + 1
        } else if target < matrix[row][middle] {
            right = middle - 1
        } else {
            return true
        }
    }
    return false

}

func sortColors(nums []int) {
    low, mid, hi := 0, 0, len(nums)-1

    for low <= hi {
        if nums[low] == 2 {
            nums[low], nums[hi] = nums[hi], nums[low]
            hi--
        } else if nums[low] == 0 {
            nums[low], nums[mid] = nums[mid], nums[low]
            mid++
            low++
        } else {
            low++
        }
    }
}

func minWindow(s string, t string) string {
    start, end := 0, 0
    targetCharacterFrequency := make(map[uint8]int)
    currentCharacterFrequency := make(map[uint8]int)
    distinctCharacterCount := 0
    minSubstring := ""

    for index := range t {
        targetCharacterFrequency[t[index]]++
    }

    for end < len(s) {
        currentCharacterFrequency[s[end]]++
        if targetCharacterFrequency[s[end]] != 0 &&
            targetCharacterFrequency[s[end]] == currentCharacterFrequency[s[end]] {
            distinctCharacterCount++
        }

        for distinctCharacterCount == len(targetCharacterFrequency) {
            if minSubstring == "" {
                minSubstring = s[start:end+1]
            }
            if end - start + 1 < len(minSubstring) {
                minSubstring = s[start:end+1]
            }

            currentCharacterFrequency[s[start]]--
            if currentCharacterFrequency[s[start]] < targetCharacterFrequency[s[start]] {
                distinctCharacterCount--
            }

            start++
        }
        end++
    }

    return minSubstring
}

func backtrack(n, k, start int, arr []int, ans *[][]int) {
    if len(arr) == k {
        comb := make([]int, k)
        copy(comb, arr)
        *ans = append(*ans, comb)
        return
    }
    for i := start; i <= n-k+(len(arr)+1); i++ {
        arr = append(arr, i)
        backtrack(n, k, i+1, arr, ans)
        arr = arr[:len(arr)-1]
    }
}

func combine(n int, k int) [][]int {
    ans := [][]int{}
    backtrack(n, k, 1, []int{}, &ans)
    return ans
}

