/**
 * Definition for a binary tree node.
 * type TreeNode struct {
 *     Val int
 *     Left *TreeNode
 *     Right *TreeNode
 * }
 */
func inorderTraversal(root *TreeNode) []int {
    res := []int{}
    stack := []*TreeNode{}
    cur := root

    for cur != nil || len(stack) > 0 {
        if cur != nil {
            stack = append(stack, cur)
            cur = cur.Left
        } else {
            cur, stack = stack[len(stack)-1], stack[:len(stack)-1]
            res = append(res, cur.Val)
            cur = cur.Right
        }
    }
    return res
}

var cache map[[2]int]bool
var st1 string
var st2 string
var st3 string

func isInterleave(s1 string, s2 string, s3 string) bool {
    if len(s1)+len(s2) != len(s3) {
        return false
    }
    cache = make(map[[2]int]bool)
    st1 = s1
    st2 = s2
    st3 = s3
    return dfs(0, 0)
}

func dfs(i, j int) bool {
    if i >= len(st1) && j >= len(st2) {
        return true
    }

    val, ok := cache[[2]int{i, j}]

    if ok {
        return val
    }

    if i < len(st1) && st1[i] == st3[i+j] && dfs(i+1, j) {
        return true
    }
    if j < len(st2) && st2[j] == st3[i+j] && dfs(i, j+1) {
        return true
    }

    cache[[2]int{i, j}] = false
    return false
}

func isValidBST(root *TreeNode) bool {
    return isValid(root, nil, nil)
}

func isValid(root, min, max *TreeNode) bool {
    if root == nil {
        return true
    }

    if min != nil && root.Val <= min.Val {
        return false
    }

    if max != nil && root.Val >= max.Val {
        return false
    }

    return isValid(root.Left, min, root) && isValid(root.Right, root, max)
}

func isSameTree(p *TreeNode, q *TreeNode) bool {
    if p == nil && q == nil {
        return true
    }

    if p == nil || q == nil || p.Val != q.Val {
        return false
    }

    return isSameTree(p.Left, q.Left) && isSameTree(p.Right, q.Right)
}

func levelOrder(root *TreeNode) [][]int {
    // nil check
        if root == nil {
            return nil
        }

        var result [][]int
        level := 0
        q := make([]*TreeNode,1)
        q[0] = root
        for len(q) > 0 {
            curLen := len(q)
            //add elements to the queue per level
            for i := 0; i < curLen; i++ {
              //queue implementation : delete element from front(1st element of slice)
                node := q[0]
                q = q[1:]

                if len(result) <= level {
                 //create new slice with first value of the level and append to result matrix
                    result = append(result,[]int{node.Val})
                }else {
                //add values to the slice created per level
                    result[level] = append(result[level],node.Val)
                }

                //queue implementation : add element at Back( after last element of slice by append)
                //add left node at queue
                if node.Left != nil {
                    q = append(q,node.Left)
                }
                //add Right node at queue
                if node.Right != nil{
                    q = append(q,node.Right)
                }
            }
            //increment the level after adding current elements to result
            level++
        }
        return result

    }

func maxDepth(root *TreeNode) int {
    if root == nil {
        return 0
    }

    left := maxDepth(root.Left)
    right := maxDepth(root.Right)

    if left > right {
        return 1 + left
    }

    return right + 1
}

func buildTree(preorder []int, inorder []int) *TreeNode {
    if len(preorder) == 0 || len(inorder) == 0 {
        return nil
    }

    root := &TreeNode{Val: preorder[0]}
    mid := index(inorder, preorder[0])
    root.Left = buildTree(preorder[1: mid + 1], inorder[:mid])
    root.Right = buildTree(preorder[mid + 1:], inorder[mid + 1:])
    return root
}

