    var charMapS, charMapT [128]byte

    for i := range s {
        charS, charT := s[i], t[i]
        if (charMapS[charS] != 0 && charMapS[charS] != charT) ||
            (charMapT[charT] != 0 && charMapT[charT] != charS) {
