func invertTree(root *TreeNode) *TreeNode {
    if root == nil {
        return root
    }

    left := invertTree(root.Left)
    root.Left = invertTree(root.Right)
    root.Right = left

    return root
}

func kthSmallest(root *TreeNode, k int) int {
    stack := make([]*TreeNode, 0, k)

    for {
        for root != nil {
            stack = append(stack, root)
            root = root.Left
        }

        root = stack[len(stack) - 1]
        stack = stack[:len(stack) - 1]

        k--
        if k == 0 {
            return root.Val
        }

        root = root.Right
    }

    return -1
}

/**
Move slow and fast pointer along the list.
Slow pointer nodes are added to reversed list.
When no more fast move is possible, iterate
along slow and back along reversed list while
checking for value equality

Time: O(N)
Space: O(1)
**/

/**
 * Definition for singly-linked list.
 * type ListNode struct {
 *     Val int
 *     Next *ListNode
 * }
 */
func isPalindrome(head *ListNode) bool {
    slow, fast := head, head
    var rev *ListNode

    for fast != nil && fast.Next != nil {
        fast = fast.Next.Next
        next_slow := slow.Next
        slow.Next = rev
        rev = slow
        slow = next_slow
    }

    // if fast is not null, slow is middle  of
    // odd length list which is skipped
    // if fast is null, slow is first element of
    // the 2nd half of even length list
    if fast != nil {
        slow = slow.Next
    }

    for slow != nil {
        if slow.Val != rev.Val {
            return false
        }
        slow = slow.Next
        rev = rev.Next
    }

    return true
}

/**
 * Definition for a binary tree node.
 * type TreeNode struct {
 *     Val   int
 *     Left  *TreeNode
 *     Right *TreeNode
 * }
 */

func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
    if p.Val > root.Val && q.Val > root.Val {
        return lowestCommonAncestor(root.Right, p, q)
    }

    if p.Val < root.Val && q.Val < root.Val {
        return lowestCommonAncestor(root.Left, p, q)
    }

    return root
}

/**
 * Definition for a binary tree node.
 * type TreeNode struct {
 *     Val int
 *     Left *TreeNode
 *     Right *TreeNode
 * }
 */
func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
    if root == nil || p == root || q == root {
        return root
    }

    left := lowestCommonAncestor(root.Left, p, q)
    right := lowestCommonAncestor(root.Right, p, q)

    if left == nil {
        return right
    }

    if right == nil {
        return left
    }

    return root
}

func productExceptSelf(nums []int) []int {
    res := make([]int, len(nums))

    prefix := 1
    for i, num := range nums {
        res[i] = prefix
        prefix *= num
    }

    postfix := 1
    for i := len(nums) - 1; i >= 0; i-- {
        res[i] *= postfix
        postfix *= nums[i]
    }
    return res
}

func maxSlidingWindow(nums []int, k int) []int {
    // get top/last element of queue: q[len(q)-1]
    // pop/remove from the top/last element of queue: q[:len(q)-1]
    // remove left value from queue: q[1:]
    output := []int{}
    q := make([]int, 0)
    l, r := 0, 0

    for r < len(nums) {
        // pop smaller values from q
        for len(q) != 0 && nums[q[len(q)-1]] < nums[r] {
            q = q[:len(q)-1]
        }
        q = append(q, r)

        // remove left val from window
        if l > q[0] {
            q = q[1:]
        }

        if (r + 1) >= k {
            output = append(output, nums[q[0]])
            l++
        }
        r++
    }
    return output
}

