    for i := range dp {
        dp[i] = MX
    }

    dp[0] = 0
    for i := 1; i <= n; i++ {
        mn := MX
        j := 1
        for i-j*j >= 0 {
            mn = min(mn, dp[i-j*j]+1)
            j++
        }
