func (s byNum) Less(i, j int) bool {return s[i][NUM] > s[j][NUM]}

func canPartitionMemoization(nums[] int) bool {
    count := make(map[int]int)
    sum := 0
    for _, n := range nums {
        count[n] += 1
        sum += n
    }

    if sum % 2 != 0 {
        return false
    }

    numsF := make([][]int, len(count))
    idx := 0
    for num, freq := range count {
        numsF[idx] = []int{num, freq}
        idx++
    }
    sort.Sort(byNum(numsF))
    visited := make([]bool, sum/2 + 1)
    visited[0] = true
    return solveCanPartition(visited, numsF, sum/2)
}

func solveCanPartition(visited []bool, nums [][]int, target int) bool {
    if visited[target] {
        return target == 0
    }
    visited[target] = true

    for index := predecessor(nums, target); index < len(nums); index++ {
        nums[index][FREQ]--
        if nums[index][FREQ] >= 0 && solveCanPartition(visited, nums, target - nums[index][NUM]) {
            return true
        }
        nums[index][FREQ]++
    }

    return false
}

func predecessor(nums [][]int, target int) int {
    l := 0
    h := len(nums) - 1
    for h - l > 1 {
        m := (h + l)/2
        if nums[m][NUM] > target {
            l = m + 1
        } else {
            h = m
        }
    }

    if nums[l][0] <= target {
        return l
    } else if nums[h][0] <= target {
        return h
    } else {
        return math.MaxInt32
    }
}

func pacificAtlantic(heights [][]int) [][]int {
    ROWS, COLS := len(heights), len(heights[0])
    pac, atl := make(map[int]bool), make(map[int] bool)

    var dfs func(int, int, map[int]bool, int)
    dfs = func(r, c int, visit map[int]bool, prevHeight int) {
        if (
            visit[r*COLS + c] ||
            r < 0 ||
            c < 0 ||
            r == ROWS ||
            c == COLS ||
            heights[r][c] < prevHeight) {
            return;
        }
        visit[r*COLS + c] = true
        dfs(r + 1, c, visit, heights[r][c])
        dfs(r - 1, c, visit, heights[r][c])
        dfs(r, c + 1, visit, heights[r][c])
        dfs(r, c - 1, visit, heights[r][c])
    }

    for c := 0; c < COLS; c++ {
        dfs(0, c, pac, heights[0][c])
        dfs(ROWS - 1, c, atl, heights[ROWS - 1][c])
    }

    for r := 0; r < ROWS; r++ {
        dfs(r, 0, pac, heights[r][0])
        dfs(r, COLS - 1, atl, heights[r][COLS - 1])
    }

    res := make([][]int, 0)
    for r := 0; r < ROWS; r++ {
        for c := 0; c < COLS; c++ {
            if pac[r*COLS + c] && atl[r*COLS + c] {
                res = append(res, []int{r, c})
            }
        }
    }
    return res
}

func characterReplacement(s string, k int) int {
    count := make(map[byte]int)
