func findSum(nums []int, idx int, target int, memo map[string]int) int {
    key := fmt.Sprint(idx)+"*"+fmt.Sprint(target)

    if val, ok := memo[key]; ok {
        return val
    }

    if idx == len(nums) {
        if target == 0 {
            return 1
        }

        return 0
    }

    res := findSum(nums, idx+1, target+nums[idx], memo) + findSum(nums, idx+1, target-nums[idx], memo)

    memo[key] = res

    return res
}

func nextGreaterElement(nums1 []int, nums2 []int) []int {
    nums1idx := make(map[int]int)
    ans := []int{}
    for i, v := range nums1 {
        nums1idx[v] = i
        ans = append(ans, -1)
    }
    stack := []int{}

    for _, v := range nums2 {
        for len(stack) > 0 && stack[len(stack)-1] < v {
            val := stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            idx := nums1idx[val]
            ans[idx] = v
        }

        if _, e := nums1idx[v]; !e {
            continue
        }
        stack = append(stack, v)
    }
    return ans
}

func change(amount int, coins []int) int {

    row := make([]int, amount+1)
    row[0] = 1

    for i := len(coins) - 1; i >= 0; i-- {

        nextRow := make([]int, amount+1)
        nextRow[0] = 1

        for a := 1; a < amount+1; a++ {
            nextRow[a] = row[a]
            if a-coins[i] >= 0 {
                nextRow[a] += nextRow[a-coins[i]]
            }
        }

        row = nextRow
    }

    return row[amount]
}

