func findRedundantConnection(edges [][]int) []int {
    parent := make([]int, len(edges)+1)

    for i := 0; i < len(parent); i++ {
        parent[i] = i
    }

    for _, edge := range edges {
        if find(parent, edge[0]) == find(parent, edge[1]) {
            return edge
        }

        unify(parent, edge[0], edge[1])
    }

    return []int{}
}

func find(parent []int, num int) int {
    if parent[num] == num {
        return num
    }

    return find(parent, parent[num])
}

func unify(parent []int, x, y int) {
    parent[find(parent, y)] = find(parent, x)
}

func maxAreaOfIsland(grid [][]int) int {
    row, col := len(grid), len(grid[0])
    res := 0

    for i := 0; i < row; i++ {
        for j := 0; j < col; j++ {
            if grid[i][j] == 1 {
                curr := dfs(grid, i, j)
                if curr > res {
                    res = curr
                }
            }
        }
    }

    return res
}

func dfs(grid [][]int, row, col int) int {
    if row < 0 || row >= len(grid) || col < 0 || col >= len(grid[0]) {
        return 0
    }

    if grid[row][col] == 0 {
        return 0
    }

    grid[row][col] = 0

    return dfs(grid, row+1, col) + dfs(grid, row-1, col) + dfs(grid, row, col+1) + dfs(grid, row, col-1) + 1
}

