func pivotIndex(nums []int) int {
    total := 0
    for _, n := range(nums) {
        total += n
    }

    leftSum := 0
    for i := 0; i < len(nums); i++ {
        rightSum := total - nums[i] - leftSum
        if leftSum == rightSum {
            return i
        }
        leftSum += nums[i]
    }
    return -1
}

func asteroidCollision(asteroids []int) []int {

    stack := []int{}
    diff := 0

    for _, asteroid := range asteroids {
        for len(stack) > 0 && stack[len(stack)-1] > 0 && asteroid < 0 {
            diff = stack[len(stack)-1] + asteroid
            if diff < 0 {
                // asteroid larger than top of stack, destroys it
                stack = stack[0 : len(stack)-1]
            } else if diff == 0 {
                // asteroid and top of stack equal, both destroyed
                stack = stack[0 : len(stack)-1]
                asteroid = 0
            } else {
                // asteroid smaller than top of stack, gets destroyed
                asteroid = 0
            }
        }
        if asteroid != 0 {
            stack = append(stack, asteroid)
        }
    }

    return stack
}

func dailyTemperatures(temperatures []int) []int {
    result := make([]int, len(temperatures))

    for i := len(temperatures) - 1; i >= 0; i-- {
        j := i + 1

        for j < len(temperatures) && temperatures[j] <= temperatures[i] {
            if result[j] <= 0 {
                break
            }
            j += result[j]
        }

        if j < len(temperatures) && temperatures[j] > temperatures[i] {
            result[i] = j - i
        }

    }
    return result
}

