import "sort"

func kthLargestNumber(nums []string, k int) string {
    sort.Slice(nums, func(i, j int) bool {
        if len(nums[i]) != len(nums[j]) {
            return len(nums[i]) > len(nums[j])
        }
        for idx := range nums[i] {
            if nums[i][idx] != nums[j][idx] {
                return nums[i][idx] > nums[j][idx]
            }
        }
        return true
    })
    return nums[k-1]
}

func maxProduct(s string) (res int) {
    dp := make([]int, 1<<len(s))
    mask := (1 << len(s)) - 1
    palindromeSize := func(s string, mask int) (res int) {
        i, j := 0, len(s)
        for i <= j {
            if mask&(1<<i) == 0 {
                i++
            } else if mask&(1<<j) == 0 {
                j--
            } else if s[i] != s[j] {
                return 0
            } else {
                if i == j {
                    res++
                } else {
                    res += 2
                }
                i++
                j--
            }
        }
        return res
    }

    max := func(a, b int) int {
        if a > b {
            return a
        }
        return b
    }

    for m := 1; m <= mask; m++ {
        dp[m] = palindromeSize(s, m)
    }

    for m1 := mask; m1 > 0; m1-- {
        if dp[m1]*(len(s)-dp[m1]) <= res {
            continue
        }
        for m2 := mask ^ m1; m2 > 0; m2 = (m2 - 1) & (mask ^ m1) {
            res = max(res, dp[m1]*dp[m2])
        }
    }
    return
}

/**
 * Definition for singly-linked list.
 * type ListNode struct {
 *     Val int
 *     Next *ListNode
 * }
 */
func pairSum(head *ListNode) int {
    // find mid of a list
    slow := head
    fast := head.Next
    for fast != nil && fast.Next != nil {
        slow = slow.Next
        fast = fast.Next.Next
    }

    // reverse links in 2nd half
    second := reverse(slow.Next)
    // split into 2 lists
    slow.Next = nil

    // traverse two lists with pointers and compare twin sum
    first := head
    var maxSum int
    for first != nil && second != nil {
        maxSum = max(maxSum, first.Val+second.Val)
        first = first.Next
        second = second.Next
    }
    return maxSum
}

func reverse(node *ListNode) *ListNode {
    var curr, prev *ListNode = node, nil
    for curr != nil {
        tmp := curr.Next
        curr.Next = prev
        prev = curr
        curr = tmp
    }
    return prev
}

